const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topics={phones:{resolution:'Schools should ban smartphones during the school day.',a:['Protect sustained attention','A school-wide rule removes a recurring distraction and makes classroom expectations consistent. If phones interrupt attention, reducing access could support learning.','Reduce social pressure','Time away from constant notifications could give students more room for face-to-face interaction.'],n:['Teach responsible use instead','Students need opportunities to learn digital self-regulation. A blanket ban removes the opportunity to practice it in a supported environment.','Preserve useful access','Phones can support accessibility, family communication, and learning tasks. A strict ban risks treating these needs as exceptions rather than designing for them.'],ar:'A restriction can include documented accessibility and emergency exceptions. Digital literacy can still be taught through supervised devices.',nr:'Exceptions increase enforcement complexity. The affirmative still needs evidence that a full-day ban outperforms a classroom-only restriction.',claims:['Phone restrictions improve academic outcomes.','Reduced phone access improves student wellbeing.','Supervised use builds transferable self-regulation.'],queries:['school phone bans academic achievement systematic review','school smartphone policies wellbeing study','digital self regulation classroom intervention'],winner:'Negative',why:'The negative offers a narrower alternative and identifies a gap in the full-day policy. The affirmative explains a plausible mechanism, but has not established why an all-day ban is necessary.',scores:[23,24,17,22,24,19]},homework:{resolution:'Schools should eliminate mandatory homework.',a:['Make time outside school equitable','Students have unequal access to quiet space and adult support. Mandatory work outside school can reward those resources rather than learning.','Protect time for recovery','Rest, family time, and independent interests matter. School can prioritize focused practice during supported classroom time.'],n:['Practice supports mastery','Some skills need repeated practice. Short, purposeful assignments can reveal misunderstandings and prepare students for more independent study.','Improve homework rather than abolish it','Limits on workload and flexible formats could address burden while keeping useful opportunities to practice.'],ar:'Supported practice during the school day gives every learner access to feedback and resources.',nr:'Moving all practice into class has an opportunity cost. The affirmative must show how the timetable can accommodate it.',claims:['Mandatory homework widens achievement gaps.','Eliminating homework improves wellbeing without harming learning.','Purposeful homework improves long-term retention.'],queries:['homework achievement meta analysis age students','homework student wellbeing systematic review','retrieval practice homework retention study'],winner:'Negative',why:'The negative distinguishes poor assignments from purposeful practice and proposes a less sweeping response. The affirmative needs age-specific evidence and a credible replacement for outside practice.',scores:[23,23,18,24,24,19]},uniforms:{resolution:'Schools should require students to wear uniforms.',a:['Create a shared identity','A common uniform could reduce visible differences in clothing and help students feel part of a school community.','Simplify daily expectations','Clear clothing expectations may reduce daily decisions and disputes over what counts as appropriate dress.'],n:['Protect student expression','Clothing is a way to express identity. Restrictions require a clear educational justification rather than an assumption that similarity creates belonging.','Consider the cost to families','Required items and approved suppliers can add costs. A flexible dress code could meet practical needs without prescribing a uniform.'],ar:'A low-cost policy with financial assistance could address affordability while retaining consistent expectations.',nr:'Assistance needs funding, and a common outfit does not itself prove reduced bullying or stronger belonging.',claims:['Uniforms reduce bullying linked to clothing.','Uniform policies improve school belonging.','Uniform requirements increase household clothing costs.'],queries:['school uniform bullying evidence study','school uniforms belonging systematic review','school uniform family cost research'],winner:'Negative',why:'The negative makes the tradeoff between expression and institutional benefit explicit. The affirmative offers plausible benefits but has not demonstrated that uniform requirements produce them.',scores:[22,23,17,24,23,19]},ai:{resolution:'Students should be allowed to use AI tools for school assignments.',a:['Offer timely support','AI can offer alternative explanations and help students get unstuck when direct support is unavailable. Students should explain their own reasoning and disclose tool use.','Teach critical AI literacy','Guided use allows students to practice checking outputs, protecting personal information, and recognizing limitations.'],n:['Protect independent learning','If a tool does the reasoning, an assignment may no longer reveal what the student understands. Permission needs task-specific boundaries.','Address unequal access and errors','Students may have different access to paid tools. Confident but inaccurate outputs can mislead learners who lack the knowledge to check them.'],ar:'Require process notes, oral checks, and disclosure so assistance remains visible and understanding can be assessed.',nr:'Those safeguards demand teacher time. The affirmative must show how they work consistently across subjects and age groups.',claims:['AI assistance improves independent learning outcomes.','Disclosure and oral checks reliably detect overreliance.','Paid AI access creates measurable learning advantages.'],queries:['generative AI education independent learning randomized study','AI assessment oral examination student understanding','generative AI education access inequality study'],winner:'Affirmative',why:'The affirmative pairs permission with specific checks on learning and disclosure. This is a stronger response than unrestricted use, although the case remains provisional until evidence supports the safeguards.',scores:[25,24,19,23,23,18]}};
let topic='phones',tab='debate',current=null,running=false;let sessions=[];try{sessions=JSON.parse(localStorage.getItem('forum-sessions')||'[]');if(!Array.isArray(sessions))sessions=[]}catch{}function persist(){try{localStorage.setItem('forum-sessions',JSON.stringify(sessions.slice(0,20)))}catch{}$('#historyCount').textContent=sessions.length}persist();
function message(role,title,body,round='OPENING CASE'){return `<article class="message"><div class="message-head"><span class="pill">${role}</span>${title}<small>${round}</small></div>${body}</article>`}function caseBody(c){return `<h4>1. ${esc(c[0])}</h4><p>${esc(c[1])}</p><h4>2. ${esc(c[2])}</h4><p>${esc(c[3])}</p><span class="pill">Evidence needed · reasoning is not proof</span>`}
function generic(resolution){return {resolution,a:['Establish a meaningful benefit',`For “${resolution}”, define who benefits and how the proposed change produces that benefit. Compare it with what happens under the current policy.`,'Make implementation credible','Identify the decision-maker, resources, exceptions, and a realistic way to measure success.'],n:['Test necessity and tradeoffs','Ask whether a less restrictive alternative achieves the same goal. Identify who bears the costs and which benefits remain uncertain.','Challenge the causal link','A plausible story is not evidence. Test whether the proposed policy causes the desired outcome and whether results transfer to this setting.'],ar:'A strong affirmative response should explain why the alternative is insufficient and show how implementation addresses the most serious cost.',nr:'A strong negative response should identify a concrete counterexample or a feasible alternative, rather than relying only on uncertainty.',claims:['The proposal causes the expected benefit.','The proposal is feasible in this setting.','The alternative achieves comparable benefits at lower cost.'],queries:[resolution+' evidence systematic review',resolution+' implementation evaluation',resolution+' alternatives comparison'],winner:'No decision',why:'This custom-resolution worksheet provides argument prompts, not generated topic expertise. Develop both cases and add evidence before a meaningful verdict can be reached.',scores:null}}
function render(){if(!current)return;const d=current.data;$('#flags').textContent=d.claims.length;$('#sessionState').textContent='SESSION COMPLETE';$('#export').disabled=false;if(tab==='debate'){$('#output').innerHTML=`<div class="notice">Practice simulation · ${current.custom?'Custom-resolution argument worksheet':'Prepared illustrative cases'}. These are not live AI agents. No empirical claims have been independently verified.</div>`+message('Affirmative','The case for',caseBody(d.a))+message('Negative','The case against',caseBody(d.n))+message('Affirmative','Responding to the challenge',`<p>${esc(d.ar)}</p>`,'REBUTTAL')+message('Negative','Testing the response',`<p>${esc(d.nr)}</p>`,'REBUTTAL')+message('Researcher','Before you make these claims…',`<p>${d.claims.length} empirical claims need supporting sources. Open Evidence review to build your source checklist.</p>`,'SOURCE AUDIT');}else if(tab==='evidence'){$('#output').innerHTML=`<div class="notice">Research checklist · Links open external searches, not verified citations. Assess the author, methods, date, and relevance before using a source.</div>`+d.claims.map((c,i)=>message('Needs a source',`Claim ${i+1}`,`<p>${esc(c)}</p><p>Look for: ${esc(d.queries[i])}</p><a href="https://scholar.google.com/scholar?q=${encodeURIComponent(d.queries[i])}" target="_blank" rel="noopener noreferrer">Find research ↗</a>`,'UNVERIFIED')).join('')+`<div class="message"><h4>Your evidence notes</h4><p>Record citations, limitations, and which claim each source supports.</p><textarea class="notes" id="notes" aria-label="Evidence notes" placeholder="Author, title, year, URL, and what the evidence actually supports…">${esc(current.notes||'')}</textarea></div>`;$('#notes').oninput=e=>{current.notes=e.target.value;const n=sessions.findIndex(x=>x.id===current.id);if(n>=0)sessions[n]=current;persist()}}else{$('#output').innerHTML=message('Judge',d.winner==='No decision'?'Further preparation needed':`${d.winner} has the stronger illustrative case`,`${d.scores?`<div class="scorecards"><div class="score"><span>AFFIRMATIVE</span><strong>${d.scores[0]+d.scores[1]+d.scores[2]}<small>/100</small></strong></div><div class="score"><span>NEGATIVE</span><strong>${d.scores[3]+d.scores[4]+d.scores[5]}<small>/100</small></strong></div></div><div class="criterion"><span>Reasoning / 35</span><span>${d.scores[0]} — ${d.scores[3]}</span></div><div class="criterion"><span>Response & feasibility / 35</span><span>${d.scores[1]} — ${d.scores[4]}</span></div><div class="criterion"><span>Evidence readiness / 30</span><span>${d.scores[2]} — ${d.scores[5]}</span></div>`:''}<h4>What made the difference</h4><p>${esc(d.why)}</p><h4>Make your next case stronger</h4><p>Define the policy precisely, answer the strongest objection, and support the disputed causal claim with relevant research.</p><span class="pill">Illustrative rubric · fixed practice scores · not an AI assessment</span>`,'EXPLAINED VERDICT')}}
function setTab(t){tab=t;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));render()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{if(running)return;topic=b.dataset.topic;$('#resolution').value=topics[topic].resolution;document.querySelectorAll('[data-topic]').forEach(x=>x.classList.toggle('selected',x===b))});$('#resolution').oninput=()=>document.querySelectorAll('[data-topic]').forEach(x=>x.classList.toggle('selected',topics[x.dataset.topic].resolution===$('#resolution').value.trim()));
$('#run').onclick=()=>{if(running)return;const resolution=$('#resolution').value.trim();if(resolution.length<12){$('#resolution').setCustomValidity('Enter a complete resolution of at least 12 characters.');$('#resolution').reportValidity();return}$('#resolution').setCustomValidity('');const match=Object.keys(topics).find(k=>topics[k].resolution.toLowerCase()===resolution.toLowerCase());current={id:Date.now(),date:new Date().toISOString(),data:match?topics[match]:generic(resolution),custom:!match,notes:''};sessions.unshift(current);sessions=sessions.slice(0,20);persist();setTab('debate');$('.debate-section').scrollIntoView({behavior:'smooth',block:'start'})};$('#resolution').addEventListener('input',()=>$('#resolution').setCustomValidity(''));
$('#history').onclick=()=>{const list=$('#historyList');list.innerHTML=sessions.length?sessions.map((s,i)=>`<button class="history-item" data-session="${i}">${esc(s.data.resolution)}<small>${new Date(s.date).toLocaleString()} · Practice simulation</small></button>`).join(''):'<p class="notice">Your saved sessions will appear here after you start a debate.</p>';list.querySelectorAll('button').forEach(b=>b.onclick=()=>{current=sessions[Number(b.dataset.session)];$('#resolution').value=current.data.resolution;setTab('debate');$('#historyDialog').close()});$('#historyDialog').showModal()};$('#closeHistory').onclick=()=>$('#historyDialog').close();$('#workspace').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('#export').onclick=()=>{if(!current)return;const d=current.data;const txt=`THE FORUM — PRACTICE SIMULATION\nResolution: ${d.resolution}\n\nAFFIRMATIVE\n${d.a.join('\n\n')}\nRebuttal: ${d.ar}\n\nNEGATIVE\n${d.n.join('\n\n')}\nRebuttal: ${d.nr}\n\nRESEARCH CHECKLIST (unverified)\n${d.claims.join('\n')}\n\nJUDGE (illustrative fixed assessment)\n${d.winner}\n${d.why}\n\nYOUR NOTES\n${current.notes||''}`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/plain'}));a.download='forum-debate-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
